

local __rs={
[1]="<color=#7d3b17>【武器神通】</color>\n<color=#65615f>·使持续伤害威力提升10%，造成暴击伤害时以100%几率施加3回合【猛毒】，此效果每回合可生效1次</color>",
[2]="螭咬",
[3]="上古神兽凤凰落下的一根翎羽炼化而成的道兵。其炙热无比，一剑焚空",
[4]="焰羽",
[5]="参与仙盟地宫活动获取",
[6]="一把剑承天光之威的绝世道兵，其锋芒锐不可当，无物不断",
[7]="天光",
[8]="能御万古长青之气的绝世道兵，轻弹此剑可发出阵阵悠歌，使万物焕发生机",
[9]="长气",
[10]="传闻以天海之水锻造的绝世道兵，其剑锋可使百川归流，四海清净",
[11]="浮都",
[12]="以天岳之石炼制的绝世道兵，其重若山岳，势若万钧，挥舞起来震天动地",
[13]="关山",
[14]="青竹蜂云剑",
[15]="万化千霆剑",
[16]="月落孤影",
[17]="赤光轩辕剑",
[18]="远古巨灵神得大道真意以自身躯体炼化成的道兵，有开山劈石，移山填海之能",
[19]="巨灵",
[20]="孤途",
[21]="鬼门关",
[22]="红尘三千",
[23]="杠上开花",
[24]="斩寿·不归",
[25]="<color=#7d3b17>【武器神通】</color>\n<color=#65615f>·暴击伤害提升15%，每当回合数为单数时，携带者获得1回合【灾劫】</color>",
[26]="灾星",
[27]="雷霄",
[28]="陷阵",
[29]="<color=#7d3b17>【武器神通】</color>\n<color=#65615f>·使持续伤害威力提升15%，每回合行动后为2名队友祛除1个减益状态，并在祛除成功后为其添加2回合【新生】</color>",
[30]="霞伞",
[31]="心魇",
[32]="折桂令",
[33]="长夜清寒",
[34]="太常",
[35]="岁月静好",
[36]="于雪山之巅的一枝寒梅所炼道兵，纵冰封千里，万物归寂，仍可凌寒独放",
[37]="咏梅",
[38]="今朝有酒今朝醉，明日愁来明日休",
[39]="醉今朝",
[40]="玉麟笔刀",
[41]="知礼",
[42]="情比天高",
[43]="喵喵大墨笔",
[44]="上古蛟龙以毕生修为凝聚的宝珠，后经仙人以大道真意炼制至成的道兵",
[45]="蛟珠",
[46]="降雷珠",
[47]="红棘",
[48]="朱雀环",
[49]="赤霄环",
[50]="月满今宵",
[51]="以传说中的蛊巫灵蟾之力炼成的道兵，光华内蕴，似有生息流转其间。",
[52]="灵蟾珠",
[53]="鬼哭骸",
[54]="由上古邪修收集千万魂魄养蛊炼制而成的道兵，幡成时千里之地乌云蔽日，万魂嚎哭！",
[55]="万魂幡",
[56]="星河日暮",
[57]="福祸无常",
[58]="仙界大能寻访三界五行奇物所炼之道兵，相传炼成时扇面上五行真意绵绵流转，生生不息。",
[59]="五行扇",
[60]="江山图",
[61]="云中客",
[62]="青鸾鸣霜",
[63]="天生我狂",
[64]="此物原为仙宫玉兔飞升得道时，斩三尸所用之法器，后与其斩落的三尸一并遗留凡间，经大道真意蕴养，得月照精华化为道兵，其辉如明月，落若银河",
[65]="玉轮",
}
